-- post: seven-checks-before-buying-used (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-20026, now(), now(), 'seed', 'seven-checks-before-buying-used', 'POST', 0, true, '65f023632bc26470c104b75f', 'PUBLISHED', now() - interval '4 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -290003, "categoryIds": [-251], "tags": ["مستعمل", "فحص", "occasion"], "authorName": "كريم عبد الحميد", "featured": true}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200051, now(), now(), 'seed', '<p>معظم المشترين يفحصون لون السيارة ولا يفحصون سمك طلائها. هذه قائمة بما ننصح كل عميل بالنظر إليه بنفسه، حتى مع وجود تقرير مكتوب.</p><h2>1. سمك الطلاء</h2><p>جهاز قياس بسيط يكشف إن كانت اللوحة قد أُعيد رشها. الفرق بين 110 و 250 ميكرون يعني إصلاح حادث.</p><h2>2. فواصل الأبواب والكبوت</h2><p>يجب أن تكون متساوية العرض من أعلى إلى أسفل. الفارق يعني تعديلًا في الهيكل.</p><h2>3. أرقام الشاسيه</h2><p>قارن الرقم على الهيكل بالرقم في الرخصة. أي اختلاف ينهي الصفقة فورًا.</p><h2>4. الزيوت</h2><p>زيت المحرك الأسود اللزج يعني إهمال صيانة. زيت الفتيس بلون بني محروق يعني تكلفة قادمة.</p><h2>5. الإطارات</h2><p>أربعة إطارات من ماركات مختلفة وتواريخ متباعدة تدل على مالك يقتصد في غير موضعه.</p><h2>6. كمبيوتر السيارة</h2><p>اطلب قراءة الأعطال المخزّنة. الأعطال الممسوحة حديثًا تظهر في عدّاد الجاهزية.</p><h2>7. التجربة على طريق سريع</h2><p>عشرون دقيقة داخل المدينة لا تكشف اهتزاز الفرامل أو انحراف المقود. اخرج على الدائري.</p>', 'سبعة فحوص قبل شراء سيارة مستعملة', 'سبعة فحوص قبل شراء سيارة مستعملة', 'ما يجب أن تنظر إليه بنفسك قبل توقيع عقد سيارة مستعملة: الهيكل، الطلاء، الزيوت، والكمبيوتر.', 'مستعمل, فحص, occasion', 'سبعة فحوص قبل شراء سيارة مستعملة | المدونة', 'seven-checks-ar', 'ar', -20026, 'TRANSLATED', 'خمس دقائق في المعرض توفّر عليك خمسة آلاف جنيه في الورشة. هذه أهم سبع نقاط.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200052, now(), now(), 'seed', '<p>La plupart des acheteurs regardent la couleur de la voiture et jamais l''épaisseur de sa peinture. Voici ce que nous conseillons de vérifier soi-même, rapport écrit ou pas.</p><h2>1. L''épaisseur de peinture</h2><p>Un simple mesureur révèle une aile repeinte. L''écart entre 110 et 250 microns signe une reprise accidentelle.</p><h2>2. Les jeux de portes et de capot</h2><p>Ils doivent être constants du haut vers le bas. Une variation trahit une déformation de structure.</p><h2>3. Les numéros de série</h2><p>Comparez le numéro frappé sur la caisse et celui de la carte grise. La moindre différence met fin à la discussion.</p><h2>4. Les fluides</h2><p>Une huile moteur noire et épaisse annonce un entretien négligé. Une huile de boîte brun brûlé annonce une facture.</p><h2>5. Les pneumatiques</h2><p>Quatre marques différentes à des dates éloignées désignent un propriétaire qui a économisé au mauvais endroit.</p><h2>6. Le calculateur</h2><p>Demandez la lecture des défauts mémorisés. Un effacement récent se voit aux compteurs de disponibilité.</p><h2>7. L''essai sur voie rapide</h2><p>Vingt minutes en ville ne révèlent ni vibration au freinage ni tirage de direction. Sortez sur le périphérique.</p>', 'Sept vérifications avant d''acheter une occasion', 'Sept vérifications avant d''acheter une occasion', 'Ce qu''il faut regarder soi-même avant de signer : carrosserie, peinture, fluides, calculateur.', 'مستعمل, فحص, occasion', 'Sept vérifications avant d''acheter une occasion | Le blog', 'sept-verifications-occasion', 'fr', -20026, 'TRANSLATED', 'Cinq minutes au showroom vous épargnent cinq mille livres à l''atelier. Voici les sept points.', null, null, null)
on conflict (description_id) do nothing;
