INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200053, now(), now(), 'seed', '<h2>تكلفة الكيلومتر</h2><p>سيارة كهربائية متوسطة تستهلك نحو 17 كيلوواط/ساعة لكل مئة كيلومتر. بشرائح الاستهلاك المنزلي، هذا أقل من ثلث تكلفة سيارة بنزين مكافئة.</p><h2>ما لا يظهر في الحسبة السريعة</h2><ul><li>التأمين أعلى بنحو 15% بسبب تكلفة البطارية</li><li>الإطارات تتآكل أسرع بفعل الوزن والعزم</li><li>الصيانة الدورية أرخص: لا زيت، لا فلاتر، فرامل تدوم أطول</li></ul><h2>نقطة التعادل</h2><p>عند خمسة عشر ألف كيلومتر سنويًا، يستغرق فارق السعر الابتدائي نحو أربع سنوات ليُسترد.</p>', 'كم تكلّف السيارة الكهربائية فعليًا في مصر؟', 'كم تكلّف السيارة الكهربائية فعليًا في مصر؟', 'حساب واقعي لتكلفة الكيلومتر في السيارة الكهربائية مقابل البنزين في الظروف المصرية.', 'كهربائي, تكلفة, électrique', 'تكلفة السيارة الكهربائية في مصر | المدونة', 'ev-running-costs-ar', 'ar', -20027, 'TRANSLATED', 'الكهرباء أرخص من البنزين بفارق كبير، لكن التأمين وقطع الغيار يقلّصان الفارق.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200054, now(), now(), 'seed', '<h2>Le coût au kilomètre</h2><p>Un électrique moyen consomme environ 17 kWh aux cent kilomètres. Aux tarifs résidentiels, cela représente moins du tiers d''une essence équivalente.</p><h2>Ce que le calcul rapide oublie</h2><ul><li>L''assurance est environ 15 % plus chère, à cause de la batterie</li><li>Les pneumatiques s''usent plus vite, sous l''effet du poids et du couple</li><li>L''entretien courant coûte moins : pas d''huile, pas de filtres, des freins qui durent</li></ul><h2>Le point d''équilibre</h2><p>À quinze mille kilomètres par an, le surcoût à l''achat est amorti en quatre ans environ.</p>', 'Ce que coûte réellement un véhicule électrique en Égypte', 'Ce que coûte réellement un véhicule électrique en Égypte', 'Un calcul honnête du coût au kilomètre d''un véhicule électrique face à l''essence, en conditions égyptiennes.', 'كهربائي, تكلفة, électrique', 'Le coût réel d''un électrique en Égypte | Le blog', 'cout-reel-electrique-egypte', 'fr', -20027, 'TRANSLATED', 'L''électricité est bien moins chère que l''essence, mais l''assurance et les pièces réduisent l''écart.', null, null, null)
on conflict (description_id) do nothing;
