INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200055, now(), now(), 'seed', '<p>الأعطال الصيفية ليست مفاجئة، بل مؤجلة من الشتاء. هذه قائمة مايو.</p><h2>الرادياتير</h2><p>افحص تركيز سائل التبريد لا مستواه فقط. الماء وحده يغلي عند مئة درجة، بينما الخليط الصحيح يتحمل حتى 128.</p><h2>التكييف</h2><p>إن احتاج شحن غاز كل صيف، فهناك تسريب. الشحن المتكرر يفسد الضاغط.</p><h2>البطارية</h2><p>الحرارة تقتل البطاريات أكثر من البرد. بطارية عمرها أربع سنوات في مصر تعادل ستًا في أوروبا.</p><h2>ضغط الإطارات</h2><p>اضبطه على البارد صباحًا. الارتفاع الظاهر بعد القيادة طبيعي ولا يُفرَّغ منه هواء.</p>', 'تجهيز السيارة لصيف القاهرة', 'تجهيز السيارة لصيف القاهرة', 'فحص الرادياتير والتكييف والبطارية والإطارات قبل موجة الحر.', 'صيانة, تكييف, entretien', 'تجهيز السيارة لصيف القاهرة | المدونة', 'summer-cooling-ar', 'ar', -20028, 'TRANSLATED', 'خمسون درجة على الأسفلت تكشف كل تهاون في نظام التبريد. قائمة ما يجب فحصه في مايو.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200056, now(), now(), 'seed', '<p>Les pannes d''été ne sont pas des surprises : ce sont des négligences d''hiver. Voici la liste de mai.</p><h2>Le radiateur</h2><p>Contrôlez la concentration du liquide, pas seulement le niveau. L''eau seule bout à cent degrés ; un mélange correct tient jusqu''à 128.</p><h2>La climatisation</h2><p>Si elle demande une recharge chaque été, c''est qu''elle fuit. Les recharges répétées détruisent le compresseur.</p><h2>La batterie</h2><p>La chaleur tue plus de batteries que le froid. Quatre ans en Égypte valent six en Europe.</p><h2>La pression des pneus</h2><p>Réglez-la à froid, le matin. La hausse constatée après roulage est normale : on ne dégonfle pas.</p>', 'Préparer sa voiture à l''été cairote', 'Préparer sa voiture à l''été cairote', 'Radiateur, climatisation, batterie et pneumatiques : les contrôles à faire avant la canicule.', 'صيانة, تكييف, entretien', 'Préparer sa voiture à l''été cairote | Le blog', 'preparer-ete-cairote', 'fr', -20028, 'TRANSLATED', 'Cinquante degrés sur le bitume révèlent toute négligence du circuit de refroidissement. La liste de mai.', null, null, null)
on conflict (description_id) do nothing;
