-- post: suv-or-sedan (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-20029, now(), now(), 'seed', 'suv-or-sedan', 'POST', 3, true, '65f023632bc26470c104b75f', 'PUBLISHED', now() - interval '31 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -290006, "categoryIds": [-251], "tags": ["SUV", "سيدان", "comparatif"], "authorName": "كريم عبد الحميد", "featured": false}')
