INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200057, now(), now(), 'seed', '<p>السؤال الشائع « أيهما أفضل » لا إجابة له. السؤال المفيد: أين تقود، وكم يومًا في الأسبوع؟</p><h2>المطبات والأرصفة</h2><p>ارتفاع الـ SUV ميزة حقيقية على الطرق الجانبية والمطبات غير المدهونة. هنا يتفوق بوضوح.</p><h2>الزحام واستهلاك الوقود</h2><p>الوزن الأعلى يعني استهلاكًا أعلى بنحو 15% في الزحام، وهو ما يشعر به من يقود يوميًا في وسط القاهرة.</p><h2>الركن</h2><p>طول السيدان أقل بنصف متر تقريبًا، وهو فارق يقرر أحيانًا وجود مكان من عدمه.</p><h2>الخلاصة</h2><p>القيادة اليومية داخل المدينة: سيدان. الطرق الصحراوية والعائلة الكبيرة والرحلات: SUV.</p>', 'سيدان أم SUV؟ السؤال الخطأ', 'سيدان أم SUV؟ السؤال الخطأ', 'مقارنة عملية بين السيدان والـ SUV في ظروف القيادة المصرية.', 'SUV, سيدان, comparatif', 'سيدان أم SUV؟ | المدونة', 'suv-or-sedan-ar', 'ar', -20029, 'TRANSLATED', 'الفارق الحقيقي ليس في الشكل بل في المطبات والزحام واستهلاك الوقود.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200058, now(), now(), 'seed', '<p>« Lequel est le mieux » n''a pas de réponse. La question utile est : où conduisez-vous, et combien de jours par semaine ?</p><h2>Dos-d''âne et trottoirs</h2><p>La garde au sol d''un SUV est un avantage réel sur les voies secondaires et les ralentisseurs non peints. Il gagne nettement ici.</p><h2>Embouteillages et consommation</h2><p>Le surpoids coûte environ 15 % de consommation en circulation dense — ce que ressent quiconque traverse le centre du Caire chaque jour.</p><h2>Le stationnement</h2><p>Une berline mesure environ un demi-mètre de moins, et ce demi-mètre décide parfois de l''existence d''une place.</p><h2>En résumé</h2><p>Trajets urbains quotidiens : berline. Pistes désertiques, grande famille, longs trajets : SUV.</p>', 'Berline ou SUV ? La mauvaise question', 'Berline ou SUV ? La mauvaise question', 'Une comparaison concrète entre berline et SUV dans les conditions de conduite égyptiennes.', 'SUV, سيدان, comparatif', 'Berline ou SUV ? | Le blog', 'berline-ou-suv', 'fr', -20029, 'TRANSLATED', 'La vraie différence ne tient pas à la silhouette mais aux dos-d''âne, aux embouteillages et à la consommation.', null, null, null)
on conflict (description_id) do nothing;
