INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200059, now(), now(), 'seed', '<p>الورشة في المعادي هي المكان الذي تُرفض فيه السيارات، لا الذي تُجمَّل فيه.</p><h2>ثلاثون سيارة في الأسبوع</h2><p>يدخل الورشة نحو ثلاثين سيارة أسبوعيًا، ويُرفض منها بين خمس وثماني في المتوسط. أكثر أسباب الرفض شيوعًا: إصلاح هيكل غير معلن.</p><h2>ساعتان لكل سيارة</h2><p>الفحص الكامل يستغرق ساعتين، منها أربعون دقيقة على الرافعة وحدها.</p><h2>لماذا لا نصلح ونبيع؟</h2><p>لأن إصلاح الهيكل يمكن إخفاؤه، ولا يمكن ضمانه. ما لا نستطيع ضمانه لا نبيعه.</p>', 'داخل ورشة المعادي', 'داخل ورشة المعادي', 'جولة في الورشة التي يمر بها كل سيارة مستعملة قبل العرض.', 'ورشة, فحص, atelier', 'داخل ورشة المعادي | المدونة', 'inside-maadi-ar', 'ar', -20030, 'TRANSLATED', 'أربع رافعات، جهازا قياس طلاء، وثلاثون سيارة أسبوعيًا لا يمر منها الجميع.', null, null, null)
