INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200060, now(), now(), 'seed', '<p>L''atelier de Maadi est l''endroit où l''on refuse des voitures, pas celui où on les maquille.</p><h2>Trente voitures par semaine</h2><p>Une trentaine de véhicules y entrent chaque semaine ; cinq à huit sont refusés. Motif le plus fréquent : une reprise de structure non déclarée.</p><h2>Deux heures par véhicule</h2><p>L''inspection complète dure deux heures, dont quarante minutes sur le pont.</p><h2>Pourquoi ne pas réparer et vendre ?</h2><p>Parce qu''une reprise de structure peut se cacher mais pas se garantir. Ce que nous ne pouvons pas garantir, nous ne le vendons pas.</p>', 'Dans l''atelier de Maadi', 'Dans l''atelier de Maadi', 'Visite de l''atelier par lequel passe chaque véhicule d''occasion avant la mise en vente.', 'ورشة, فحص, atelier', 'Dans l''atelier de Maadi | Le blog', 'dans-latelier-de-maadi', 'fr', -20030, 'TRANSLATED', 'Quatre ponts, deux mesureurs de peinture, et trente voitures par semaine dont toutes ne passent pas.', null, null, null)
on conflict (description_id) do nothing;
