INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200061, now(), now(), 'seed', '<h2>الفجوات أهم من الأختام</h2><p>ابحث عن الفترات الطويلة بين الزيارات، لا عن عدد الأختام. فجوة ثمانية عشر شهرًا أخطر من صفحة ناقصة.</p><h2>القفزات في العداد</h2><p>عشرة آلاف كيلومتر في زيارة، ثم أربعون ألفًا في التالية، تعني إما استخدامًا مختلفًا أو عدادًا معدَّلًا.</p><h2>البنود المتكررة</h2><p>تغيير نفس الحساس ثلاث مرات يعني أن أحدًا لم يعالج السبب.</p>', 'كيف تقرأ سجل الصيانة', 'كيف تقرأ سجل الصيانة', 'ما تكشفه دفاتر الصيانة فعلًا عن حالة السيارة، وما لا تكشفه.', 'صيانة, سجل, entretien', 'كيف تقرأ سجل الصيانة | المدونة', 'reading-service-book-ar', 'ar', -20031, 'TRANSLATED', 'سجل ممتلئ بالأختام ليس دليل عناية. المهم هو المسافات بين الزيارات.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200062, now(), now(), 'seed', '<h2>Les trous comptent plus que les tampons</h2><p>Cherchez les longues périodes sans passage, pas le nombre de cachets. Un trou de dix-huit mois est plus inquiétant qu''une page manquante.</p><h2>Les sauts de compteur</h2><p>Dix mille kilomètres entre deux visites puis quarante mille : soit l''usage a changé, soit le compteur.</p><h2>Les lignes qui reviennent</h2><p>Le même capteur remplacé trois fois signifie que personne n''a traité la cause.</p>', 'Lire un carnet d''entretien', 'Lire un carnet d''entretien', 'Ce que les carnets d''entretien révèlent vraiment de l''état d''un véhicule, et ce qu''ils taisent.', 'صيانة, سجل, entretien', 'Lire un carnet d''entretien | Le blog', 'lire-un-carnet-dentretien', 'fr', -20031, 'TRANSLATED', 'Un carnet plein de tampons ne prouve rien. Ce qui compte, ce sont les intervalles.', null, null, null)
on conflict (description_id) do nothing;
